 ((select count(*) from schemas)=4 and not exists(select 1 from schemas n
  where not pg_catalog.has_schema_privilege('helpdesk_app',n.oid,'USAGE')
   or pg_catalog.has_schema_privilege('helpdesk_app',n.oid,'CREATE,USAGE WITH GRANT OPTION'))) as schema_contract_ok,
 (not exists(select 1 from expected_tables e full join tables t on t.full_name=e.name
  where e.name is null or t.oid is null or t.relkind<>'r')) as table_contract_ok,
 (not exists(select 1 from tables t join expected_tables e on e.name=t.full_name where
  pg_catalog.has_table_privilege('helpdesk_app',t.oid,'SELECT') is distinct from e.read
  or pg_catalog.has_table_privilege('helpdesk_app',t.oid,'INSERT') is distinct from e."insert"
  or pg_catalog.has_table_privilege('helpdesk_app',t.oid,'UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN')
  or pg_catalog.has_table_privilege('helpdesk_app',t.oid,'SELECT WITH GRANT OPTION,INSERT WITH GRANT OPTION,UPDATE WITH GRANT OPTION'))
  ) as table_privileges_ok,
 (not exists(select 1 from tables t join expected_tables e on e.name=t.full_name
  join pg_catalog.pg_attribute a on a.attrelid=t.oid and a.attnum>0 and not a.attisdropped where
