  or (p.prosecdef and not (p.rolsuper or p.rolbypassrls)))) as helper_settings_ok,
 (not exists(select 1 from expected_triggers e left join tables t on t.full_name=e."table"
  left join pg_catalog.pg_trigger g on g.tgrelid=t.oid and g.tgname=e.name
  left join functions p on p.oid=g.tgfoid where g.oid is null or g.tgenabled not in ('O','A')
   or g.tgisinternal or g.tgtype<>e.type or g.tgdeferrable is distinct from e.deferred
   or g.tginitdeferred is distinct from e.deferred or p.signature is distinct from e."function")
  and not exists(select 1 from pg_catalog.pg_trigger g join tables t on t.oid=g.tgrelid where g.tgenabled not in ('O','A'))) as trigger_contract_ok,
 (not exists(select 1 from expected_constraints e left join tables t on t.full_name=e."table"
  left join pg_catalog.pg_constraint c on c.conrelid=t.oid and c.conname=e.name
  where c.oid is null or c.contype::text<>e.type or not c.convalidated)
  and not exists(select 1 from pg_catalog.pg_constraint c join tables t on t.oid=c.conrelid where not c.convalidated)) as constraint_contract_ok,
 (not exists(select 1 from pg_catalog.pg_index i join tables t on t.oid=i.indrelid where not i.indisvalid or not i.indisready)
  and exists(select 1 from pg_catalog.pg_index i join pg_catalog.pg_class x on x.oid=i.indexrelid
   join tables t on t.oid=i.indrelid where t.full_name='helpdesk_core.ticket_events' and x.relname='assignment_event_version'
    and i.indisunique and i.indisvalid and i.indisready)
  and (select count(*) from pg_catalog.pg_index i join pg_catalog.pg_class x on x.oid=i.indexrelid
   join tables t on t.oid=i.indrelid where t.full_name='helpdesk_audit.write_effects'
    and x.relname in ('write_effect_revision','write_effect_source')
    and i.indisunique and i.indisvalid and i.indisready and i.indpred is not null)=2) as index_contract_ok,
 ((select count(*) from pg_catalog.pg_policy p join tables t on t.oid=p.polrelid)=(select count(*) from expected_policies)
  and not exists(select 1 from expected_policies e left join tables t on t.full_name=e."table"
   left join pg_catalog.pg_policy p on p.polrelid=t.oid and p.polname=e.name where p.oid is null
    or p.polpermissive is distinct from e.permissive or p.polcmd::text<>e.command
    or p.polroles is distinct from array[(select oid from app)]::oid[])) as policy_contract_ok,
 ((select count(*) from expected_roles)=2 and not exists(select 1 from expected_roles e left join pg_catalog.pg_roles r on r.rolname=e.name where r.oid is null
   or r.rolsuper or r.rolbypassrls or r.rolcreaterole or r.rolcreatedb or r.rolreplication or r.rolinherit
   or EXISTS(
 SELECT 1 FROM pg_catalog.pg_auth_members m WHERE m.member=r.oid
 OR (m.roleid=r.oid AND NOT ((m.member=(SELECT owner.oid FROM pg_catalog.pg_roles owner
 WHERE owner.rolcreaterole AND (owner.rolsuper OR owner.rolbypassrls)
 AND owner.rolname NOT IN ('helpdesk_app','helpdesk_resource_publisher','helpdesk_notification_worker','helpdesk_maintenance','anon','authenticated','service_role')
 AND owner.oid=(SELECT n.nspowner FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit')
 GROUP BY n.nspowner HAVING count(*)=4))
 AND m.grantor=10 AND EXISTS(SELECT 1 FROM pg_catalog.pg_roles bootstrap WHERE bootstrap.oid=10 AND bootstrap.rolsuper)
 AND m.admin_option AND NOT m.inherit_option AND NOT m.set_option) IS TRUE)))
   or exists(select 1 from schemas n where n.nspowner=r.oid or pg_catalog.has_schema_privilege(r.oid,n.oid,'USAGE') is distinct from (n.nspname=any(e.schemas)) or pg_catalog.has_schema_privilege(r.oid,n.oid,'CREATE,USAGE WITH GRANT OPTION'))
   or exists(select 1 from tables t where t.relowner=r.oid or pg_catalog.has_table_privilege(r.oid,t.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN') or pg_catalog.has_any_column_privilege(r.oid,t.oid,'SELECT,INSERT,UPDATE,REFERENCES'))
   or exists(select 1 from functions p where p.proowner=r.oid or pg_catalog.has_function_privilege(r.oid,p.oid,'EXECUTE') is distinct from (p.signature=any(e.functions)) or pg_catalog.has_function_privilege(r.oid,p.oid,'EXECUTE WITH GRANT OPTION'))
 )) as reserved_roles_ok,
 ((SELECT owner.oid FROM pg_catalog.pg_roles owner
 WHERE owner.rolcreaterole AND (owner.rolsuper OR owner.rolbypassrls)
 AND owner.rolname NOT IN ('helpdesk_app','helpdesk_resource_publisher','helpdesk_notification_worker','helpdesk_maintenance','anon','authenticated','service_role')
 AND owner.oid=(SELECT n.nspowner FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit')
 GROUP BY n.nspowner HAVING count(*)=4)) IS NOT NULL AND NOT EXISTS(
 SELECT 1 FROM pg_catalog.pg_default_acl d CROSS JOIN LATERAL pg_catalog.aclexplode(d.defaclacl) a
 WHERE d.defaclrole=(SELECT owner.oid FROM pg_catalog.pg_roles owner
 WHERE owner.rolcreaterole AND (owner.rolsuper OR owner.rolbypassrls)
 AND owner.rolname NOT IN ('helpdesk_app','helpdesk_resource_publisher','helpdesk_notification_worker','helpdesk_maintenance','anon','authenticated','service_role')
 AND owner.oid=(SELECT n.nspowner FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit')
 GROUP BY n.nspowner HAVING count(*)=4))
 AND (d.defaclnamespace=0 OR d.defaclnamespace IN (SELECT oid FROM pg_catalog.pg_namespace WHERE nspname IN ('helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit')))
 AND a.grantee<>d.defaclrole AND NOT (a.grantee=0 AND d.defaclobjtype='f' AND a.privilege_type='EXECUTE'))) as owner_defaults_ok,
 (pg_catalog.current_setting('server_version_num')::integer between 170000 and 179999
  and pg_catalog.current_setting('row_security')='on'
  and pg_catalog.current_setting('session_replication_role')='origin') as execution_settings_ok) catalogue;
 IF checked.table_count IS DISTINCT FROM 79 OR checked.unsafe_tables IS DISTINCT FROM 0
 OR checked.public_schema_access IS DISTINCT FROM FALSE OR checked.client_schema_access IS DISTINCT FROM FALSE OR checked.public_helper_execute IS DISTINCT FROM FALSE
 OR checked.schema_contract_ok IS DISTINCT FROM TRUE
 OR checked.table_contract_ok IS DISTINCT FROM TRUE
 OR checked.table_privileges_ok IS DISTINCT FROM TRUE
 OR checked.column_privileges_ok IS DISTINCT FROM TRUE
 OR checked.client_object_privileges_ok IS DISTINCT FROM TRUE
 OR checked.helper_contract_ok IS DISTINCT FROM TRUE
 OR checked.helper_privileges_ok IS DISTINCT FROM TRUE
 OR checked.helper_settings_ok IS DISTINCT FROM TRUE
 OR checked.trigger_contract_ok IS DISTINCT FROM TRUE
 OR checked.constraint_contract_ok IS DISTINCT FROM TRUE
 OR checked.index_contract_ok IS DISTINCT FROM TRUE
 OR checked.policy_contract_ok IS DISTINCT FROM TRUE
 OR checked.execution_settings_ok IS DISTINCT FROM TRUE
 OR checked.reserved_roles_ok IS DISTINCT FROM TRUE
 OR checked.owner_defaults_ok IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Exact wave2 catalogue required' USING ERRCODE='HDE06';END IF;
END $wave2_final_catalogue$;

-- Qualify the immutable parent independently of the private projection plan.
-- Same instant may have distinct public/private JSON timestamp representations.
CREATE OR REPLACE FUNCTION helpdesk_auth.hdn_notification_facts_wave2_team(target uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE p helpdesk_integration.hdn_notification_private_sources%rowtype;root helpdesk_audit.hdni_receipts%rowtype;
 e helpdesk_core.ticket_events%rowtype;f helpdesk_audit.write_effects%rowtype;c helpdesk_audit.hdn_workflow_commits%rowtype;
 facts jsonb;source jsonb;prior jsonb;BEGIN
 SELECT * INTO p FROM helpdesk_integration.hdn_notification_private_sources WHERE id=target FOR SHARE;
 IF NOT FOUND THEN RETURN helpdesk_auth.hdn_notification_facts_wave2_public(target);END IF;
 SELECT * INTO STRICT root FROM helpdesk_audit.hdni_receipts WHERE (workspace_id,account_id,ticket_id)=(p.workspace_id,p.account_id,p.ticket_id) FOR SHARE;
 facts:=helpdesk_auth.hdn_notification_facts_v024(root.event_id);
 IF facts->'source'->>'type'<>'support.created' THEN RAISE EXCEPTION 'Private root source mismatch' USING ERRCODE='HDN05';END IF;
 SELECT * INTO STRICT e FROM helpdesk_core.ticket_events WHERE (workspace_id,account_id,ticket_id,id)=(p.workspace_id,p.account_id,p.ticket_id,p.parent_event_id) FOR SHARE;
 SELECT * INTO STRICT f FROM helpdesk_audit.write_effects WHERE (workspace_id,account_id,ticket_id,event_id)=(p.workspace_id,p.account_id,p.ticket_id,p.parent_event_id) FOR SHARE;
 IF NOT f.applied OR f.actor_id<>e.actor_id OR f.kind<>e.type OR f.ticket_version<>p.source_version OR e.created_at<>p.created_at
 OR (e.data-CASE WHEN e.type IN ('ticket.status_changed','ticket.assignment_changed') THEN 'reason' ELSE '__absent__' END)<>f.expected_data THEN RAISE EXCEPTION 'Private parent mismatch' USING ERRCODE='HDN05';END IF;
 IF p.kind='internal.queue_created' THEN
  IF p.parent_event_id<>root.event_id OR e.type<>'ticket.created' OR NOT e.customer_visible OR f.transaction_id<>root.transaction_id OR p.request_id<>facts->'source'->>'requestId' THEN RAISE EXCEPTION 'Private opening mismatch' USING ERRCODE='HDN05';END IF;
 ELSE
  SELECT * INTO STRICT c FROM helpdesk_audit.hdn_workflow_commits WHERE (workspace_id,account_id,ticket_id,event_id)=(p.workspace_id,p.account_id,p.ticket_id,p.parent_event_id) FOR SHARE;
  IF c.transaction_id<>f.transaction_id OR c.actor_id<>e.actor_id OR c.core_type<>e.type OR c.to_version<>p.source_version OR c.at<>p.created_at OR c.audit->>'requestId'<>p.request_id
  OR p.kind='internal.assignment_changed' AND (c.command->>'action'<>'transfer' OR e.type<>'ticket.assignment_changed' OR e.customer_visible OR c.command->>'targetPrincipalId' IS DISTINCT FROM p.assigned_principal_id::text)
  OR p.kind='support.customer_reply' AND (c.command->>'action'<>'customer_reply' OR c.public_event->>'actorKind'<>'customer' OR NOT e.customer_visible) THEN RAISE EXCEPTION 'Private workflow mismatch' USING ERRCODE='HDN05';END IF;
  IF p.kind='support.customer_reply' THEN
   -- v024 validates actual event/outbox/effect/snapshot/receipt/resource history.
   -- The private source below owns the plan hash; the public projection must not
   -- reinterpret that plan when its UUID is shared with the parent event.
   PERFORM helpdesk_auth.hdn_notification_facts_v024(p.parent_event_id);
   IF c.from_status NOT IN ('open','waiting_customer','waiting_internal','waiting_third_party')
    OR NOT (c.to_status=c.from_status OR c.from_status='waiting_customer' AND c.to_status='open')
   THEN RAISE EXCEPTION 'Private customer return semantics changed' USING ERRCODE='HDN05';END IF;
  END IF;
 END IF;
 source:=jsonb_build_object('id',p.id,'workspaceId',p.workspace_id,'accountId',p.account_id,'ticketId',p.ticket_id,'type',p.kind,'version',p.source_version,'requestId',p.request_id,'createdAt',helpdesk_auth.hdn_workflow_iso(p.created_at));
 SELECT document INTO prior FROM helpdesk_integration.hdn_notification_plans WHERE event_id=target;
 IF prior IS NOT NULL AND prior->>'sourceHash'<>helpdesk_auth.hdni_digest(source) THEN RAISE EXCEPTION 'Private historical source mismatch' USING ERRCODE='HDN05';END IF;
 RETURN jsonb_set(facts,'{source}',source,false)||jsonb_build_object('wave2Eligible',true,'sourceAssigneeId',p.assigned_principal_id,'parentEventId',p.parent_event_id);
EXCEPTION WHEN no_data_found OR data_exception THEN RAISE EXCEPTION 'Unqualified private source' USING ERRCODE='HDN05';END$$;

-- CUSTOMER RETURN FINAL CATALOGUE
DO $wave2_final_catalogue$ DECLARE checked record;BEGIN
 IF NOT (EXISTS(SELECT 1 FROM pg_catalog.pg_roles r WHERE r.rolname='helpdesk_app'
 AND NOT(r.rolsuper OR r.rolbypassrls OR r.rolcreaterole OR r.rolcreatedb OR r.rolreplication)
 AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members m WHERE m.member=r.oid)
